"""Write a reviewable register from the generated production manifests."""
from pathlib import Path
import json

ROOT=Path(__file__).resolve().parents[2]
BASE=ROOT/'public/assets/tyaga'
models=json.loads((BASE/'models/manifest.json').read_text())['assets']
audio=json.loads((BASE/'audio/manifest.json').read_text())['assets']
ui=json.loads((BASE/'icons/manifest.json').read_text())['assets']
fonts=json.loads((BASE/'fonts/manifest.json').read_text())['assets']

lines=['# Тяга — реестр ассетов\n',
'## Происхождение\n',
'Геометрия, материалы, rig, motion clips, иконки, маршрутные иллюстрации и аудио созданы для этой игры воспроизводимыми исходниками в `art/source`. Чужие модели, записи или текстуры в эти файлы не включены. Маркер `project-original` означает оригинальный материал проекта, а не утверждение о лицензии найденного файла. Права на сторонние шрифты указаны отдельно.\n',
'Искались и рассматривались следующие реальные первичные источники. Просмотр страницы и объявленной лицензии не обозначается как получение архива.\n',
'| Набор / роль | Первичный источник и условия | Решение |',
'|---|---|---|',
'| Машина / колёса | [Kenney Car Kit](https://kenney.nl/assets/car-kit), CC0; [страница автора на itch](https://kenney-assets.itch.io/car-kit) | Страница описывает общие автомобили, грузовики и фургоны. Требуемого Тягача-6 с данной площадкой, подвеской и socket-контрактом не подтверждено. Обращение к найденному ZIP вернуло HTML, архив не импортировался. Созданы свои модель, колёса и крепления. |',
'| Камни, растительность, грунт | [Kenney Nature Kit](https://kenney.nl/assets/nature-kit), CC0 | Рассмотрен как кандидат окружения. Для согласованного силуэта и палитры произведены собственные камни/деревья/кусты/трава; файлы набора не импортировались. |',
'| Персонаж / анимация | [Kenney Animated Characters Protagonists](https://kenney.nl/assets/animated-characters-protagonists), CC0 | Готовые образы не приняты для экспедиционной одежды и инструментальных поз. Созданы собственные персонаж, rig, клипы, две головы и два рюкзака. |',
'| Механизмы / промышленное окружение | [Kenney Conveyor Kit](https://kenney-assets.itch.io/conveyor-kit) и [City Kit Industrial](https://kenney.nl/assets/city-kit-industrial) | Специфические груз, паром, подъёмник и инструментальные attachment points доступным просмотром не подтверждены. Эти модели произведены самостоятельно. Из этих наборов ничего не распространяется; лицензия конкретного неполученного архива не приписывается собственным файлам. |',
'| Удары, шаги / Foley | [Kenney Impact Sounds](https://kenney.nl/assets/impact-sounds), CC0; [RPG Audio](https://kenney.nl/assets/rpg-audio) | Рассмотрены кандидаты для материалов. Итоговый банк — собственный синтез с разными физическими тембрами, без импортированных записей. |',
'| Шрифты | [Google Fonts Golos Text](https://github.com/google/fonts/tree/main/ofl/golostext), [Rubik](https://github.com/google/fonts/tree/main/ofl/rubik), SIL OFL 1.1 | Фактические TTF и полные OFL получены, сохранены без изменений. Проверены кириллица, латиница и цифры. |\n',
'Для CC0-пакетов использована опубликованная авторами декларация; [текст CC0](https://creativecommons.org/publicdomain/zero/1.0/) прочитан. Никакие сторонние модели по этой декларации фактически не распространяются в Tyaga.\n',
'## Модели\n',
'Все runtime-файлы ниже находятся в `games/tyaga/public/assets/tyaga/models/`. Числа треугольников измерены по GLB, не оценены по скриншоту. Для каждого файла точный SHA-256, габариты, origin, collider proxy, точки крепления, анимируемые узлы и исходник записаны в [machine manifest](../public/assets/tyaga/models/manifest.json). Визуальные и серверные коллайдеры проверяются отдельно; окончательное правило задаёт авторитетное ядро.\n',
'| assetId / GLB | Габариты XYZ, м | Масса, кг | Треугольники | Исходник / способ |',
'|---|---:|---:|---:|---|']
for a in models:
    dims=' × '.join(str(d) for d in a['dimensionsXYZ'])
    src=Path(a['source']).name
    lines.append(f'| `{a["assetId"]}.glb` | {dims} | {a["massKg"] if a["massKg"] is not None else "—"} | {a["triangles"]:,} | `{src}`, оригинальная процедурная геометрия |')
lines.extend(['\nМасса отдельного инструмента отражает правило, а не суммирование декоративных частей. Передняя лебёдка, пустой ящик и опоры входят в массу машины. У платформы габариты таблицы относятся к несущей плите; поручни имеют отдельные формы/коллизии. У character ширина таблицы относится к капсуле; руки и рюкзак не увеличивают капсулу.\n',
'## Анимация и состояния\n',
'Персонаж: один 17-костный rig; `idle`, `walk`, `run`, `jump`, `fall`, `land`, `carry`, `push`, `hold`, `crank`, `repair`, `driver`, `stumble`. Проверены имена, наличие skin, веса и точки обеих рук. Варианты головы/рюкзака не размножают скелет. Материал одежды меняется независимо от важных грузов.\n',
'Техника: именованные pivot для колёс/руля/лебёдки, поршня домкрата, винта/румпеля и барьеров. Напряжение троса и состояние повреждения связываются с фактической симуляцией рендерером. Предусмотренные детали и узлы не объявляются работающими только по наличию в GLB.\n',
'## Звук\n',
'Все WAV — оригинальный детерминированный синтез `generate_audio.py`, mono 32 kHz / 16-bit PCM. [Manifest](../public/assets/tyaga/audio/manifest.json) содержит SHA, длительность, RMS/peak и loop-флаг. Записи чужих игр не использованы.\n',
'| ID / WAV | Длительность, с | Петля | Peak dBFS | Назначение |',
'|---|---:|---|---:|---|'])
for a in audio:
    lines.append(f'| `{a["assetId"]}.wav` | {a["seconds"]} | {"да" if a["loop"] else "нет"} | {a["peakDbFS"]} | Материал/событие `{a["assetId"]}` |')
lines.extend(['\nПроверены формат, отсутствие одинаковых файлов, отсутствие clipping, DC и стык loop. **Слуховая оценка тембра и игровой микс этим техническим прогоном не приняты.** Подключение события и исключение повторов reconnect проверяются в браузерной приёмке.\n',
'## Интерфейс и шрифты\n',
f'Собственные SVG: {len([a for a in ui if not a["assetId"].startswith("cover-")])} иконок инструментов/действий и три схематичные обложки маршрутов. Все исходники находятся в `generate_ui.py`; внешних картинок, stock-иконок или ссылок на CDN нет. Обложки являются авторскими иллюстрациями, не скриншотами игры.\n',
'| Семейство / файл | Право распространения / фактический файл | Изменения |',
'|---|---|---|'])
for a in fonts:
    file=Path(a['runtimePath']).name
    license_file=Path(a['licensePath']).name
    lines.append(f'| {a["assetId"]}, `{file}` | [OFL](licenses/{license_file}); копия включена в runtime рядом с TTF. SHA-256 `{a["sha256"]}` | Нет |')
lines.extend(['\n## Состояние проверки\n',
'`source/validate_art.py` проверяет фактический набор и сохраняет [VALIDATION.json](VALIDATION.json). Авторский Blender-рендер позволил отдельно оценить первую сцену; его результаты не заменяют игровой проход. Габариты груза/инструментов, коллайдеры в реальной карте, связь состояний и анимаций, desktop/touch, максимальная нагрузка и прослушивание требуют записи в общей приёмке игры.\n',
'Производственные артефакты не зависят от наличия поисковых страниц, Blender или генераторов на клиенте. Все файлы обслуживаются из текущего выпуска.'])
(ROOT/'art/ASSET_REGISTER.md').write_text('\n'.join(lines)+'\n')
print('Wrote art/ASSET_REGISTER.md from actual manifests')
